const predictGame = async (path: string, extraParams: Record<string, any> = {}) => {
  pendingPath.value = path
  pendingExtraParams.value = extraParams

  try {
    const body = { path, ...extraParams }
    const res = await fetch(`${BASE_URL}/game/predict_game`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    })
    const data = await res.json()

    if (data.status === 200) {
      if (data.data === '') {
        // 成功
        ElMessage.success('添加游戏成功')
        clearAddInput()
        // 重新加载分类（数量可能变化），然后刷新当前分类
        await loadCategories()
        if (currentCategoryId.value) {
          await loadGamesByCategory(currentCategoryId.value)
        }
        return
      }
      // 需要进一步处理
      const result = data.data
      if (result.is_many) {
        manyConfirmDialogVisible.value = true
      }
      if (result.need_pass) {
        passwordDialogVisible.value = true
      }
    } else {
      ElMessage.error(data.message || '添加失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，添加游戏失败')
    console.error(e)
  }
