  }
  if (searchParams.value.dateRange && searchParams.value.dateRange[0] && searchParams.value.dateRange[1]) {
    body.insert_time_start = `${searchParams.value.dateRange[0]}T00:00:00Z`
    body.insert_time_end = `${searchParams.value.dateRange[1]}T23:59:59Z`
  }
  if (searchParams.value.category_id) {
    body.category_id = searchParams.value.category_id
  }
  if (searchParams.value.series) {
    body.series = searchParams.value.series
  }
  if (searchParams.value.description) {
    body.description = searchParams.value.description
  }
  if (searchParams.value.isPlay !== null) {
    body.is_play = searchParams.value.isPlay
  }

  // 检查是否至少填写了一项
  if (Object.keys(body).length === 0) {
    ElMessage.warning('请至少填写一个搜索条件')
    return
  }

  try {
    const res = await fetch(`${BASE_URL}/game/get_game_by_condition`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    })
    const data = await res.json()
    if (data.status === 200) {
      games.value = data.data
      // 搜索结果不点亮导航
      currentCategoryId.value = ''
    } else {
      ElMessage.error(data.message || '搜索失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，搜索失败')
    console.error(e)
  }
}

