    icon_path: game.IconPath,
    name: game.Name,
    nick_name: game.NickName,
    description: game.Description,
    path: game.Path,
    start_path: game.StartPath,
    category_name: game.Category?.Name || '未分类',
    category_id: game.Category?.Id || '000000',
    series: game.Series,
    is_play: game.IsPlay
  }
}

// 启动游戏
const openGame = async (game: Game) => {
  // 检查是否有启动路径
  if (!game.StartPath?.trim()) {
    ElMessage.warning('该游戏没有设置启动路径')
    return
  }
  try {
    const res = await fetch(`${BASE_URL}/game/open_game`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(convertGameToSnakeCase(game))
    })
    const data = await res.json()
    if (data.status === 200) {
      ElMessage.success('已尝试打开游戏')
    } else {
      ElMessage.error(data.message || '打开失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，打开游戏失败')
    console.error(e)
  }
}

