<template>
  <div class="game-manager">
    <!-- 顶部导航栏 -->
    <div class="navbar">
      <div class="navbar-brand">GameManager</div>
      <div
        v-for="category in categories"
        :key="category.Id"
        class="navbar-item"
        :class="{ active: currentCategoryId === category.Id }"
        @click="selectCategory(category)"
      >
        {{ category.Name }} <span class="count">({{ category.Num }})</span>
      </div>
    </div>

    <!-- 搜索和拖拽区域 -->
    <div class="top-section">
      <!-- 添加游戏区域 -->
      <div class="add-area">
        <div class="add-title">添加游戏</div>
        <el-input
          v-model="addPath"
          placeholder="请输入文件/文件夹绝对路径"
          clearable
          class="add-input"
        />
        <el-button type="primary" @click="handleAddGame" :disabled="!addPath">
          添加游戏
        </el-button>
      </div>

      <!-- 搜索区域 -->
      <div class="search-area">
        <div class="search-row">
          <el-input
            v-model="searchParams.keyword"
            placeholder="请输入关键词"
            clearable
            @clear="handleSearch"
          />
          <el-button type="primary" @click="handleSearch">搜索</el-button>
        </div>
        <div class="search-row">
          <el-date-picker
            v-model="searchParams.dateRange"
            type="daterange"
            range-separator="至"
            start-placeholder="开始日期"
            end-placeholder="结束日期"
            format="YYYY-MM-DD"
            value-format="YYYY-MM-DD"
            placeholder="时间范围（加入时间）可以清空"
          />
          <el-select v-model="searchParams.category_id" placeholder="类型" clearable>
            <el-option
              v-for="cat in categories"
              :key="cat.Id"
              :label="cat.Name"
              :value="cat.Id"
            />
          </el-select>
          <el-input
            v-model="searchParams.series"
            placeholder="系列"
            clearable
          />
          <el-input
            v-model="searchParams.description"
            placeholder="部分描述"
            clearable
          />
          <el-select v-model="searchParams.isPlay" placeholder="是否玩过" clearable>
            <el-option label="玩过" :value="true"></el-option>
            <el-option label="未玩过" :value="false"></el-option>
          </el-select>
        </div>
      </div>
    </div>

    <!-- 游戏卡片网格 -->
    <div class="games-container">
      <div
        v-for="game in games"
        :key="game.Id"
        class="game-card"
        :class="[game.IsPlay ? 'played' : 'unplayed']"
      >
        <div class="game-header">
          <div class="game-icon">
            <img v-if="game.IconPath" :src="game.IconPath" alt="icon" />
            <div v-else class="game-icon-default">
              <span class="game-icon-text">{{ (game.NickName || game.Name).charAt(0).toUpperCase() }}</span>
            </div>
          </div>
          <div class="game-title">
            <h2>{{ game.NickName || game.Name }}</h2>
            <div v-if="game.Series" class="game-series">{{ game.Series }}</div>
          </div>
        </div>

        <div class="game-path">{{ game.Path }}</div>

        <div class="game-description">
          <p>{{ game.Description || '暂无简介' }}</p>
        </div>

        <div class="game-actions">
          <el-button type="primary" @click="openGame(game)">启动</el-button>
          <el-button type="primary" @click="editGame(game)">编辑</el-button>
          <el-button type="primary" @click="viewGame(game)">查看</el-button>
          <el-button type="danger" @click="deleteGame(game)">删除</el-button>
        </div>
      </div>

      <el-empty v-if="games.length === 0" description="暂无游戏数据" />
    </div>

    <!-- 编辑对话框 -->
    <el-dialog
      v-model="editDialogVisible"
      title="编辑游戏"
      width="600px"
      @close="resetEditForm"
    >
      <el-form :model="editForm" label-width="100px">
        <el-form-item label="游戏名称">
          <el-input v-model="editForm.name" />
        </el-form-item>
        <el-form-item label="别名">
          <el-input v-model="editForm.nick_name" />
        </el-form-item>
        <el-form-item label="描述">
          <el-input type="textarea" v-model="editForm.description" />
        </el-form-item>
        <el-form-item label="游戏路径">
          <el-input v-model="editForm.path" />
        </el-form-item>
        <el-form-item label="启动路径">
          <el-input v-model="editForm.start_path" placeholder="可留空" />
        </el-form-item>
        <el-form-item label="图标路径">
          <el-input v-model="editForm.icon_path" placeholder="可留空" />
        </el-form-item>
        <el-form-item label="分类">
          <el-select v-model="editForm.category_id" placeholder="选择分类">
            <el-option
              v-for="cat in categories"
              :key="cat.Id"
              :label="cat.Name"
              :value="cat.Id"
            />
          </el-select>
        </el-form-item>
        <el-form-item label="系列">
          <el-input v-model="editForm.series" />
        </el-form-item>
        <el-form-item label="是否玩过">
          <el-switch v-model="editForm.is_play" />
        </el-form-item>
        <el-form-item label="游戏图片">
          <el-upload
            ref="editImageUpload"
            :action="uploadUrl"
            :auto-upload="false"
            :on-change="handleImageChange"
            :file-list="editForm.imgs"
            multiple
            :limit="10"
          >
            <el-button type="primary">选择图片</el-button>
          </el-upload>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="editDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitEdit">确定</el-button>
      </template>
    </el-dialog>

    <!-- 查看详情对话框 -->
    <el-dialog
      v-model="viewDialogVisible"
      title="游戏详情"
      width="800px"
    >
      <div class="game-detail" v-if="currentGame">
        <div class="detail-header">
          <div class="detail-icon" v-if="currentGame.IconPath">
            <img :src="currentGame.IconPath" alt="icon" />
          </div>
          <div class="detail-info">
            <h2>{{ currentGame.NickName || currentGame.Name }}</h2>
            <p><strong>路径：</strong>{{ currentGame.Path }}</p>
            <p><strong>启动路径：</strong>{{ currentGame.StartPath || '未设置' }}</p>
            <p><strong>系列：</strong>{{ currentGame.Series || '无' }}</p>
            <p><strong>分类：</strong>{{ getCategoryName(currentGame.Category?.Id) }}</p>
            <p><strong>状态：</strong>{{ currentGame.IsPlay ? '已玩过' : '未玩过' }}</p>
            <p><strong>添加时间：</strong>{{ formatDate(currentGame.InsertTime) }}</p>
          </div>
        </div>

        <div class="detail-description" v-if="currentGame.Description">
          <h3>描述</h3>
          <p>{{ currentGame.Description }}</p>
        </div>

        <div class="detail-images" v-if="gameImages.length > 0">
          <h3>游戏截图</h3>
          <div class="images-grid">
            <div v-for="(img, index) in gameImages" :key="index" class="image-item">
              <img :src="`data:image/jpeg;base64,${img}`" alt="screenshot" />
            </div>
          </div>
        </div>

        <div class="detail-actions">
          <el-button type="primary" @click="openExplorer(currentGame.Path)">
            在资源管理器打开
          </el-button>
        </div>
      </div>
    </el-dialog>

    <!-- 删除确认对话框 -->
    <el-dialog
      v-model="deleteDialogVisible"
      title="确认删除"
    >
      <p>确定要删除这个游戏吗？是否同时删除源文件？</p>
      <template #footer>
        <el-button @click="deleteDialogVisible = false">取消</el-button>
        <el-button @click="confirmDelete(false)">否</el-button>
        <el-button type="danger" @click="confirmDelete(true)">是</el-button>
      </template>
    </el-dialog>

    <!-- 密码输入对话框 -->
    <el-dialog
      v-model="passwordDialogVisible"
      title="需要密码"
      width="400px"
    >
      <el-input v-model="passwordInput" placeholder="请输入压缩包密码" />
      <template #footer>
        <el-button @click="passwordDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="confirmPassword">确定</el-button>
      </template>
    </el-dialog>

    <!-- 批量添加确认对话框 -->
    <el-dialog
      v-model="manyConfirmDialogVisible"
      title="批量添加确认"
      width="400px"
    >
      <p>文件夹内没有找到可执行文件，需要将其作为一个分类进行批量添加吗？</p>
      <template #footer>
        <el-button @click="manyConfirmDialogVisible = false">否</el-button>
        <el-button type="primary" @click="confirmManyAdd">是</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script lang="ts" setup>
import { ref, onMounted, computed } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'

const BASE_URL = ''

interface Category {
  Id: string
  Name: string
  Num: number
}

interface Game {
  Id: string
  IconPath: string
  Name: string
  NickName: string
  Series: string
  Description: string
  Path: string
  StartPath: string
  Category: {
    Id: string
    Name: string
    Num: number
  }
  Imgs: string[]
  IsPlay: boolean
  IsDel: boolean
  InsertTime: string
}

interface SearchParams {
  keyword: string
  dateRange: [string, string] | null
  category_id: string
  series: string
  description: string
  isPlay: boolean | null
}

interface EditForm {
  id: string
  name: string
  nick_name: string
  description: string
  path: string
  start_path: string
  icon_path: string
  category_id: string
  series: string
  is_play: boolean
  imgs: File[]
}

// 状态
const categories = ref<Category[]>([])
const currentCategoryId = ref<string>('')
const games = ref<Game[]>([])
const searchParams = ref<SearchParams>({
  keyword: '',
  dateRange: null,
  category_id: '',
  series: '',
  description: '',
  isPlay: null
})

const addPath = ref('')
const pendingPath = ref('')
const pendingExtraParams = ref<Record<string, any>>({})

// 对话框
const editDialogVisible = ref(false)
const viewDialogVisible = ref(false)
const deleteDialogVisible = ref(false)
const passwordDialogVisible = ref(false)
const manyConfirmDialogVisible = ref(false)

const currentGame = ref<Game | null>(null)
const gameToDelete = ref<Game | null>(null)
const gameImages = ref<string[]>([])
const passwordInput = ref('')

const editForm = ref<EditForm>({
  id: '',
  name: '',
  nick_name: '',
  description: '',
  category_id: '',
  series: '',
  is_play: false,
  imgs: [],
  path: '',
  start_path: '',
  icon_path: ''
})

const uploadUrl = computed(() => `${BASE_URL}/game/edit_game`)

// 获取所有分类
const loadCategories = async () => {
  try {
    const res = await fetch(`${BASE_URL}/game/get_all_category`)
    const data = await res.json()
    if (data.status === 200) {
      // 过滤掉数量为0的分类
      categories.value = data.data.filter((cat: Category) => cat.Num > 0)
      // 默认选中第一个
      if (categories.value.length > 0 && !currentCategoryId.value) {
        currentCategoryId.value = categories.value[0].Id
        await loadGamesByCategory(currentCategoryId.value)
      }
    } else {
      ElMessage.error(data.message || '获取分类失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，获取分类失败')
    console.error(e)
  }
}

// 根据分类获取游戏
const loadGamesByCategory = async (categoryId: string) => {
  try {
    const res = await fetch(`${BASE_URL}/game/get_game_by_category?category_id=${categoryId}`)
    const data = await res.json()
    if (data.status === 200) {
      games.value = data.data
    } else {
      ElMessage.error(data.message || '获取游戏列表失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，获取游戏列表失败')
    console.error(e)
  }
}

// 选择分类
const selectCategory = async (category: Category) => {
  currentCategoryId.value = category.Id
  await loadGamesByCategory(category.Id)
}

// 手动添加游戏
const handleAddGame = () => {
  let path = addPath.value.trim()
  // 去除两边的引号
  path = path.replace(/^["']|["']$/g, '')
  if (!path) {
    ElMessage.warning('请输入路径')
    return
  }
  predictGame(path)
}

// 清空添加路径输入框
const clearAddInput = () => {
  addPath.value = ''
}

// 预测游戏
const predictGame = async (path: string, extraParams: Record<string, any> = {}) => {
  pendingPath.value = path
  pendingExtraParams.value = extraParams

  try {
    const body = { path, ...extraParams }
    const res = await fetch(`${BASE_URL}/game/predict_game`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    })
    const data = await res.json()

    if (data.status === 200) {
      if (data.data === '') {
        // 成功
        ElMessage.success('添加游戏成功')
        clearAddInput()
        // 重新加载分类（数量可能变化），然后刷新当前分类
        await loadCategories()
        if (currentCategoryId.value) {
          await loadGamesByCategory(currentCategoryId.value)
        }
        return
      }
      // 需要进一步处理
      const result = data.data
      if (result.is_many) {
        manyConfirmDialogVisible.value = true
      }
      if (result.need_pass) {
        passwordDialogVisible.value = true
      }
    } else {
      ElMessage.error(data.message || '添加失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，添加游戏失败')
    console.error(e)
  }
}

// 确认批量添加
const confirmManyAdd = () => {
  manyConfirmDialogVisible.value = false
  pendingExtraParams.value.is_many = true
  predictGame(pendingPath.value, pendingExtraParams.value)
}

// 确认密码
const confirmPassword = () => {
  if (!passwordInput.value) {
    ElMessage.warning('请输入密码')
    return
  }
  passwordDialogVisible.value = false
  pendingExtraParams.value.password = passwordInput.value
  passwordInput.value = ''
  predictGame(pendingPath.value, pendingExtraParams.value)
}

// 搜索
const handleSearch = async () => {
  const body: Record<string, any> = {}
  if (searchParams.value.keyword) {
    body.name = searchParams.value.keyword
  }
  if (searchParams.value.dateRange && searchParams.value.dateRange[0] && searchParams.value.dateRange[1]) {
    body.insert_time_start = `${searchParams.value.dateRange[0]}T00:00:00Z`
    body.insert_time_end = `${searchParams.value.dateRange[1]}T23:59:59Z`
  }
  if (searchParams.value.category_id) {
    body.category_id = searchParams.value.category_id
  }
  if (searchParams.value.series) {
    body.series = searchParams.value.series
  }
  if (searchParams.value.description) {
    body.description = searchParams.value.description
  }
  if (searchParams.value.isPlay !== null) {
    body.is_play = searchParams.value.isPlay
  }

  // 检查是否至少填写了一项
  if (Object.keys(body).length === 0) {
    ElMessage.warning('请至少填写一个搜索条件')
    return
  }

  try {
    const res = await fetch(`${BASE_URL}/game/get_game_by_condition`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    })
    const data = await res.json()
    if (data.status === 200) {
      games.value = data.data
      // 搜索结果不点亮导航
      currentCategoryId.value = ''
    } else {
      ElMessage.error(data.message || '搜索失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，搜索失败')
    console.error(e)
  }
}

// 转换字段名为下划线格式
const convertGameToSnakeCase = (game: Game) => {
  return {
    id: game.Id,
    icon_path: game.IconPath,
    name: game.Name,
    nick_name: game.NickName,
    description: game.Description,
    path: game.Path,
    start_path: game.StartPath,
    category_name: game.Category?.Name || '未分类',
    category_id: game.Category?.Id || '000000',
    series: game.Series,
    is_play: game.IsPlay
  }
}

// 启动游戏
const openGame = async (game: Game) => {
  // 检查是否有启动路径
  if (!game.StartPath?.trim()) {
    ElMessage.warning('该游戏没有设置启动路径')
    return
  }
  try {
    const res = await fetch(`${BASE_URL}/game/open_game`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(convertGameToSnakeCase(game))
    })
    const data = await res.json()
    if (data.status === 200) {
      ElMessage.success('已尝试打开游戏')
    } else {
      ElMessage.error(data.message || '打开失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，打开游戏失败')
    console.error(e)
  }
}

// 编辑游戏
const editGame = (game: Game) => {
  currentGame.value = game
  editForm.value = {
    id: game.Id,
    name: game.Name,
    nick_name: game.NickName || '',
    description: game.Description || '',
    path: game.Path || '',
    start_path: game.StartPath || '',
    icon_path: game.IconPath || '',
    category_id: game.Category?.Id || '000000',
    series: game.Series || '',
    is_play: game.IsPlay,
    imgs: []
  }
  editDialogVisible.value = true
}

const resetEditForm = () => {
  editForm.value = {
    id: '',
    name: '',
    nick_name: '',
    description: '',
    path: '',
    start_path: '',
    icon_path: '',
    category_id: '',
    series: '',
    is_play: false,
    imgs: []
  }
}

const handleImageChange = (file: any, fileList: any) => {
  editForm.value.imgs = fileList.map((f: any) => f.raw)
}

const submitEdit = async () => {
  const formData = new FormData()
  for (const [key, value] of Object.entries(editForm.value)) {
    if (key === 'imgs') {
      (value as File[]).forEach(file => {
        formData.append('imgs', file)
      })
    } else {
      formData.append(key, String(value))
    }
  }

  try {
    const res = await fetch(`${BASE_URL}/game/edit_game`, {
      method: 'POST',
      body: formData
    })
    const data = await res.json()
    if (data.status === 200) {
      ElMessage.success('编辑成功')
      editDialogVisible.value = false
      // 重新加载分类，然后刷新列表
      await loadCategories()
      if (currentCategoryId.value) {
        loadGamesByCategory(currentCategoryId.value)
      }
    } else {
      ElMessage.error(data.message || '编辑失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，编辑失败')
    console.error(e)
  }
}

// 查看游戏详情
const viewGame = async (game: Game) => {
  currentGame.value = game
  viewDialogVisible.value = true
  gameImages.value = []

  try {
    const res = await fetch(`${BASE_URL}/game/get_game_imgs?game_id=${game.Id}`)
    const data = await res.json()
    if (data.status === 200) {
      gameImages.value = data.data
    }
  } catch (e) {
    console.error('获取图片失败', e)
  }
}

// 在资源管理器打开
const openExplorer = (path: string) => {
  // 需要通过后端打开，前端无法直接打开文件资源管理器
  // 这里发送请求让后端处理
  fetch(`${BASE_URL}/game/open_folder`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path })
  }).catch(e => console.error(e))
}

const getCategoryName = (categoryId: string) => {
  const cat = categories.value.find(c => c.Id === categoryId)
  return cat?.Name || '未分类'
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return ''
  return new Date(dateStr).toLocaleString()
}

// 删除游戏
const deleteGame = (game: Game) => {
  gameToDelete.value = game
  deleteDialogVisible.value = true
}

const confirmDelete = async (deleteSource: boolean) => {
  if (!gameToDelete.value) return

  try {
    const deleteAll = deleteSource ? 1 : 0
    const res = await fetch(`${BASE_URL}/game/delete_game?delete_all=${deleteAll}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(convertGameToSnakeCase(gameToDelete.value))
    })
    const data = await res.json()
    if (data.status === 200) {
      ElMessage.success('删除成功')
      deleteDialogVisible.value = false
      gameToDelete.value = null
      if (currentCategoryId.value) {
        await loadGamesByCategory(currentCategoryId.value)
      }
    } else {
      ElMessage.error(data.message || '删除失败')
    }
  } catch (e) {
    ElMessage.error('网络错误，删除失败')
    console.error(e)
  }
}

onMounted(() => {
  loadCategories()
})
</script>

<style lang="scss" scoped>
